import { createAdminClient, requireInternalSecret } from '../_shared/amazon/supabase.ts';
import { syncFxRates } from '../_shared/amazon/fx.ts';

function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}});}
function dateOnly(date:Date){return date.toISOString().slice(0,10);}
function daysAgo(days:number){const date=new Date();date.setUTCDate(date.getUTCDate()-days);return dateOnly(date);}
function validDate(value:unknown){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value);}

Deno.serve(async(req:Request)=>{
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  try{
    requireInternalSecret(req);
    const admin=createAdminClient();
    const body=await req.json().catch(()=>({}));
    const from=validDate(body?.from)?String(body.from):daysAgo(7);
    const to=validDate(body?.to)?String(body.to):dateOnly(new Date());
    if(from>to)throw new Error('El rango FX no es válido.');

    const {data:marketplaces,error}=await admin
      .from('amazon_marketplaces')
      .select('currency_code')
      .eq('active',true);
    if(error)throw error;
    const currencies=[...new Set((marketplaces||[]).map((row:any)=>String(row.currency_code||'').trim().toUpperCase()).filter(Boolean))];
    const result=await syncFxRates(admin,currencies,from,to);
    return response({ok:true,from,to,...result});
  }catch(error){
    return response({error:error instanceof Error?error.message:'Error interno de FX.'},401);
  }
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

const ECB_API='https://data-api.ecb.europa.eu/service/data/EXR';
const DATE_RE=/^\d{4}-\d{2}-\d{2}$/;

type Observation={date:string;currency:string;rate:number};
export type FxRateRow={
  rate_date:string;
  currency_code:string;
  rate_to_eur:number;
  source:'ECB';
  updated_at:string;
};

function csvLine(line:string){
  const values:string[]=[];
  let current='';
  let quoted=false;
  for(let index=0;index<line.length;index+=1){
    const char=line[index];
    if(char==='"'){
      if(quoted&&line[index+1]==='"'){current+='"';index+=1;continue;}
      quoted=!quoted;
      continue;
    }
    if(char===','&&!quoted){values.push(current);current='';continue;}
    current+=char;
  }
  values.push(current);
  return values;
}

export function parseEcbCsv(text:string):Observation[]{
  const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(line=>line.trim());
  if(lines.length<2)return [];
  const headers=csvLine(lines[0]).map(value=>value.trim().toUpperCase());
  const currencyIndex=headers.indexOf('CURRENCY');
  const dateIndex=headers.indexOf('TIME_PERIOD');
  const valueIndex=headers.indexOf('OBS_VALUE');
  if(currencyIndex<0||dateIndex<0||valueIndex<0)throw new Error('Formato CSV del BCE no reconocido.');

  const observations:Observation[]=[];
  for(const line of lines.slice(1)){
    const values=csvLine(line);
    const currency=String(values[currencyIndex]||'').trim().toUpperCase();
    const date=String(values[dateIndex]||'').trim();
    const rate=Number(values[valueIndex]);
    if(!currency||!DATE_RE.test(date)||!Number.isFinite(rate)||rate<=0)continue;
    observations.push({date,currency,rate});
  }
  return observations;
}

export function toRateRows(observations:Observation[]):FxRateRow[]{
  const now=new Date().toISOString();
  const rows:FxRateRow[]=observations
    .filter(row=>row.currency&&row.date&&Number.isFinite(row.rate)&&row.rate>0)
    .map(row=>({
      rate_date:row.date,
      currency_code:row.currency.toUpperCase(),
      rate_to_eur:1/row.rate,
      source:'ECB',
      updated_at:now,
    }));
  const dates=[...new Set(rows.map(row=>row.rate_date))];
  for(const date of dates)rows.push({rate_date:date,currency_code:'EUR',rate_to_eur:1,source:'ECB',updated_at:now});
  return rows;
}

function validateDate(value:string,label:string){
  if(!DATE_RE.test(value)||Number.isNaN(new Date(`${value}T00:00:00Z`).getTime()))throw new Error(`${label} no es una fecha válida.`);
}

export async function fetchEcbObservations(currencies:string[],from:string,to:string){
  validateDate(from,'from');
  validateDate(to,'to');
  if(from>to)throw new Error('El rango FX no es válido.');
  const codes=[...new Set(currencies.map(value=>String(value||'').trim().toUpperCase()).filter(value=>value&&value!=='EUR'))].sort();
  if(!codes.length)return [];

  const key=`D.${codes.join('+')}.EUR.SP00.A`;
  const url=new URL(`${ECB_API}/${key}`);
  url.searchParams.set('startPeriod',from);
  url.searchParams.set('endPeriod',to);
  url.searchParams.set('format','csvdata');
  url.searchParams.set('detail','dataonly');
  const response=await fetch(url,{headers:{Accept:'text/csv'}});
  if(!response.ok)throw new Error(`BCE FX respondió ${response.status}.`);
  return parseEcbCsv(await response.text());
}

export async function syncFxRates(admin:any,currencies:string[],from:string,to:string){
  const observations=await fetchEcbObservations(currencies,from,to);
  const rows=toRateRows(observations);
  if(!rows.length)return {observations:0,rows:0,currencies:[] as string[]};
  const {error}=await admin.from('amazon_fx_rates').upsert(rows,{onConflict:'rate_date,currency_code'});
  if(error)throw error;
  return {
    observations:observations.length,
    rows:rows.length,
    currencies:[...new Set(rows.map(row=>row.currency_code))].sort(),
  };
}
